//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::dec_lt`; the
//! native twin is `benches/native/Bench/NatDecLt.lean`.
//! Nat words on both sides (2n+1); every result stays below 2^63; operands in 16 values, so equal
//! ones are frequent

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            nat::dec_lt(&nat_arg(nat_box(x >> 60)), &nat_arg(nat_box((x >> 4) & 15))) as u64,
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
